function env(name, fallback = '') { let value = ''; try { value = $env[name] || ''; } catch (e) {} return value || fallback; }
function text(value) { return String(value || '').trim(); }
const input = typeof $json.body === 'string' ? JSON.parse($json.body || '{}') : ($json.body || $json);
const event = text(input.event || input.type).toLowerCase();
const data = input.data || input;
const key = data.key || data.message?.key || {};
const remoteJid = text(key.remoteJid || key.remoteJidAlt || data.remoteJid);
const message = data.message || {};
const messageType = text(data.messageType || Object.keys(message)[0] || 'conversation');
let messageText = text(message.conversation || message.extendedTextMessage?.text || message.imageMessage?.caption || message.videoMessage?.caption || message.documentMessage?.caption);
let contentType = 'text';
let base64 = text(data.base64 || message.base64 || message.audioMessage?.base64);
if (!messageText && messageType.toLowerCase().includes('audio')) { contentType = 'audio'; messageText = '[audio]'; }
else if (!messageText) { contentType = messageType.replace(/Message$/i, '').toLowerCase() || 'unknown'; messageText = '[' + contentType + ']'; }
const phone = remoteJid.split('@')[0].split(':')[0].replace(/\D/g, '');
const eventSupported = !event || ['messages.upsert', 'messages.update'].includes(event);
const ignoredReason = !eventSupported ? 'event_not_supported' : key.fromMe || data.fromMe ? 'outbound_event' : !remoteJid ? 'missing_remote_jid' : remoteJid.includes('@g.us') || remoteJid === 'status@broadcast' ? 'group_or_status' : !phone ? 'missing_phone' : '';
return { json: { shouldProcess: !ignoredReason, ignoredReason, event, tenant_slug: 'beautes', instance: text(input.instance || input.instanceName || 'Amanda'), remoteJid, phone, messageId: text(key.id || data.id || remoteJid + ':' + Date.now()), contactName: text(data.pushName || data.senderName || phone), messageText, contentType, base64, raw_payload: input, channel_type: 'whatsapp' } };

const original = $('Normalizar Entrada WhatsApp').item.json;
const duplicate = Boolean($json.propertyName || $json.value || $json.data);
return { json: { ...original, isDuplicate: duplicate } };

const base = $json || {};
const conversation = String(base.remoteJid || base.phone || '').trim();
if (!conversation) return [{ json: { ...base, skip_response: true, _debounce_invalid: true } }];
const tenant = 'beautes';
const listKey = 'beautes:whatsapp:debounce:list:' + tenant + ':' + conversation;
const lockKey = 'beautes:whatsapp:debounce:lock:' + tenant + ':' + conversation;
const isMedia = String(base.contentType || '').toLowerCase() !== 'text' || Boolean(base.base64);
return [{ json: { ...base, debounce_list_key: listKey, debounce_lock_key: lockKey, debounce_item: { payload: base, messageText: String(base.messageText || '').trim(), contentType: base.contentType || 'text', has_media: isMedia, messageId: base.messageId || null, received_at: Date.now() }, skip_response: false } }];

const base = $('Preparar mensagem para debounce').item.json;
const key = base.debounce_lock_key;
const value = Number($json[key] ?? $json.value ?? $json.data ?? 0);
return [{ json: { ...base, debounce_lock_value: value, debounce_leader: value === 1 } }];

const leader = $('Consolidar lock Redis').item.json;
const raw = $json.data ?? $json.debounce_messages ?? $json.value;
let values = [];
if (Array.isArray(raw)) values = raw;
else if (typeof raw === 'string' && raw.trim()) { try { const parsed = JSON.parse(raw); values = Array.isArray(parsed) ? parsed : [raw]; } catch (_) { values = [raw]; } }
const entries = values.map((value) => { try { return typeof value === 'string' ? JSON.parse(value) : value; } catch (_) { return null; } }).filter((entry) => entry?.payload);
if (!entries.length) return [{ json: { ...leader, _redis_debounced: true, skip_response: true } }];
const textParts = entries.map((entry) => String(entry.messageText || '').trim()).filter(Boolean);
const latest = entries[entries.length - 1];
const media = [...entries].reverse().find((entry) => entry.has_media) || latest;
return [{ json: { ...media.payload, messageText: textParts.join('\n\n'), debounce_list_key: leader.debounce_list_key, debounce_lock_key: leader.debounce_lock_key, _redis_debounced: true, _debounce_count: entries.length, _debounce_message_ids: entries.map((entry) => entry.messageId).filter(Boolean), skip_response: false } }];

const base = $('Restaurar lote').item.json;
const transcript = String($json.text || $json.transcription || $json.data?.text || '').trim();
return { json: { ...base, messageText: transcript || '[audio sem transcricao]', contentType: 'text', transcript } };

function normalize(value) { return String(value || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, ''); }
function hasAny(value, values) { return values.some((item) => value.includes(item)); }

const message = String($json.messageText || '').trim();
const value = normalize(message);
const coworkingTerms = ['subloc', 'sub-loc', 'coworking', 'consultorio odont', 'odontolog', 'alugar sala', 'aluguel da sala', 'locacao de sala', 'alugar consultorio', 'aluguel de consultorio', 'sala por hora', 'meia diaria'];
const isCoworkingInquiry = coworkingTerms.some((term) => value.includes(normalize(term)));
const procedureCatalog = [
  { label: 'Endolaser', aliases: ['endolaser'] },
  { label: 'Acompanhamento Pós-operatório', aliases: ['acompanhamento pos operatorio', 'pos operatorio', 'drenagem', 'ozonioterapia', 'ultrassom', 'radiofrequencia', 'led', 'laser'] },
  { label: 'Limpeza de Pele Profunda', aliases: ['limpeza de pele profunda', 'limpeza de pele', 'peeling', 'limpeza facial profunda'] },
  { label: 'Skin Booster', aliases: ['skin booster', 'skinbooster'] },
  { label: 'Toxina Botulínica (Botox)', aliases: ['toxina botulinica', 'botox'] },
  { label: 'Preenchimento Facial e Labial', aliases: ['preenchimento facial e labial', 'preenchimento facial', 'preenchimento labial', 'preenchimento', 'labial'] },
  { label: 'Estimulador de Colágeno', aliases: ['estimulador de colageno', 'colageno'] },
  { label: 'Microagulhamento', aliases: ['microagulhamento'] },
  { label: 'Massagem Modeladora', aliases: ['massagem modeladora', 'modeladora', 'massagem corporal']}
];
const detectedProcedure = procedureCatalog.find((item) => item.aliases.some((alias) => value.includes(normalize(alias))))?.label || '';
const finalProcedure = detectedProcedure || ($json.procedimento || $json.service || 'Estética');
let service = isCoworkingInquiry ? 'coworking_odontologico' : (detectedProcedure || 'estetica');
let stage = 'Atendimento Inicial';
let handoff = false;

if (hasAny(value, ['comprovante', 'pix', 'pago', 'pagamento', 'transferencia', 'recibo'])) { 
  stage = 'Validacao de Pagamento'; 
  handoff = true;
}
else if (hasAny(value, ['agendar', 'agenda', 'horario', 'marcar', 'dia', 'queria ir'])) { 
  stage = 'Agendamento'; 
}
else if (hasAny(value, ['humano', 'atendente', 'especialista', 'pessoa'])) { 
  stage = 'Atendimento Humano'; 
  handoff = true;
}

const promptText = 'Cliente: ' + $json.contactName
  + '\nTelefone: ' + $json.phone
  + '\nEtapa identificada: ' + stage
  + '\nMensagem: ' + message;

return { json: { ...$json, service, procedimento: finalProcedure, stage, handoff, isCoworkingInquiry, promptText: promptText + '\nInteresse em sublocação do coworking odontológico: ' + (isCoworkingInquiry ? 'sim' : 'não') + '\nProcedimento identificado: ' + (detectedProcedure || 'não identificado') } };

const base = $('Preparar Contexto Beautes').item.json;
const raw = String($json.output || $json.text || '').trim();
const responseText = raw;

const precisaValidacao = /(aguarde.*especialista|\bpix\b|comprovante|pagamento|pr[ée]-reservad|confirmar.*hor[áa]rio|tudo anotado)/i.test(raw);
const handoff = Boolean(base.handoff || precisaValidacao);
const stage = handoff ? 'Validacao de Pagamento/Agendamento' : base.stage;

return { json: { ...base, responseText, handoff, stage, direction: 'inbound', sender_type: 'contact', delivery_status: 'received' } };

const base = $('Preparar Resposta Beautes').item.json;
const sent = $json;
const externalMessageId = String(sent?.key?.id || sent?.message?.key?.id || sent?.id || base.messageId + ':reply');
return { json: { ...base, externalMessageId, direction: 'outbound', sender_type: 'assistant', messageText: base.responseText, delivery_status: 'sent', raw_payload: { provider: 'evolution_api', response: sent } } };
